import { useState } from 'react';
import './Chatbot.css';
import { aiApi } from '../services/api';

function Chatbot() {
  const [open, setOpen] = useState(false);
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [messages, setMessages] = useState([
    { role: 'bot', text: 'Hi, I am TechBot. Ask me for product recommendations, comparisons, or order help.' },
  ]);

  const send = async (event) => {
    event.preventDefault();
    const text = message.trim();
    if (!text) return;
    setMessages((items) => [...items, { role: 'user', text }]);
    setMessage('');
    setLoading(true);
    try {
      const data = await aiApi.chat(text);
      setMessages((items) => [...items, { role: 'bot', text: data.reply || 'I could not understand that.' }]);
    } catch {
      setMessages((items) => [...items, { role: 'bot', text: 'AI service is temporarily unavailable. Please try again.' }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="chatbot-wrap">
      {open && (
        <div className="chat-window card">
          <div className="chat-head">
            <div>
              <strong>TechBot</strong>
              <small>AI shopping assistant · online</small>
            </div>
            <button onClick={() => setOpen(false)}>×</button>
          </div>
          <div className="chat-body">
            {messages.map((item, index) => (
              <div key={`${item.role}-${index}`} className={`chat-message ${item.role}`}>{item.text}</div>
            ))}
            {loading && <div className="chat-message bot">Typing...</div>}
          </div>
          <form className="chat-input" onSubmit={send}>
            <input value={message} onChange={(event) => setMessage(event.target.value)} placeholder="Ask: best laptop under 150000" />
            <button type="submit">➤</button>
          </form>
        </div>
      )}
      <button className="chat-toggle" onClick={() => setOpen((value) => !value)} aria-label="Open AI chatbot">🤖</button>
    </div>
  );
}

export default Chatbot;
